134	export function Alerta({ tipo = 'erro', children }: { tipo?: 'erro' | 'aviso' | 'sucesso'; children: ReactNode }) {
135	  const cores = {
136	    erro: 'border-red-300 bg-red-50 text-red-900',
137	    aviso: 'border-amber-300 bg-amber-50 text-amber-900',
138	    sucesso: 'border-emerald-300 bg-emerald-50 text-emerald-900',
