147	/** Valor monetário com sinal e cor: positivo em verde, negativo em vermelho (o sinal vai no texto). */
148	export function Valor({ centavos, texto, className = '', ...props }: { centavos: number; texto: string } & HTMLAttributes<HTMLSpanElement>) {
149	  const cor = centavos < 0 ? 'text-red-700' : centavos > 0 ? 'text-emerald-800' : 'text-slate-700';
150	  return (
151	    <span className={`whitespace-nowrap font-medium tabular-nums ${cor} ${className}`} {...props}>
152	      {texto}
153	    </span>
154	  );
