1	import { useEffect, useId, useRef, useState } from 'react';
2	import { Botao, CampoTexto } from './ui';
3	
4	interface Props {
5	  titulo: string;
6	  mensagem: string;
7	  rotuloConfirmar: string;
8	  perigo?: boolean;
9	  /** Se informado, o usuário precisa digitar exatamente este texto para confirmar. */
10	  textoDigitado?: string;
11	  onConfirmar: () => void;
12	  onCancelar: () => void;
13	}
14	
15	/** Diálogo modal de confirmação. Renderize-o apenas quando estiver aberto. */
16	export function ConfirmDialog({ titulo, mensagem, rotuloConfirmar, perigo, textoDigitado, onConfirmar, onCancelar }: Props) {
17	  const idTitulo = useId();
18	  const [digitado, setDigitado] = useState('');
19	  const raiz = useRef<HTMLDivElement>(null);
20	
21	  useEffect(() => {
22	    const alvo = raiz.current?.querySelector<HTMLElement>('input, button');
23	    alvo?.focus();
24	  }, []);
25	
26	  useEffect(() => {
27	    const aoTeclar = (e: KeyboardEvent) => {
28	      if (e.key === 'Escape') onCancelar();
29	    };
30	    document.addEventListener('keydown', aoTeclar);
31	    return () => document.removeEventListener('keydown', aoTeclar);
32	  }, [onCancelar]);
33	
34	  const liberado = textoDigitado === undefined || digitado === textoDigitado;
35	
36	  return (
37	    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4">
38	      <div ref={raiz} role="dialog" aria-modal="true" aria-labelledby={idTitulo} className="w-full max-w-md rounded-lg bg-white p-5 shadow-xl">
39	        <h2 id={idTitulo} className="text-lg font-semibold text-slate-900">
40	          {titulo}
41	        </h2>
42	        <p className="mt-2 text-sm text-slate-700">{mensagem}</p>
43	        {textoDigitado !== undefined ? (
44	          <div className="mt-3">
45	            <CampoTexto label={`Digite ${textoDigitado} para confirmar`} value={digitado} onChange={(e) => setDigitado(e.target.value)} autoComplete="off" />
46	          </div>
47	        ) : null}
48	        <div className="mt-4 flex justify-end gap-2">
49	          <Botao variante="secundario" onClick={onCancelar}>
50	            Cancelar
51	          </Botao>
52	          <Botao variante={perigo ? 'perigo' : 'primario'} disabled={!liberado} onClick={onConfirmar}>
53	            {rotuloConfirmar}
54	          </Botao>
55	        </div>
56	      </div>
57	    </div>
58	  );
59	}
