1	import { useState } from 'react';
2	import { baixarArquivo } from '../lib/download';
3	import type { Problema } from '../state/store';
4	import { useStore } from '../state/store';
5	import { Alerta, Botao, Cartao } from './ui';
6	import { ConfirmDialog } from './ConfirmDialog';
7	
8	/** Tela exibida quando os dados salvos estão corrompidos ou vêm de uma versão mais nova. */
9	export function FalhaCarregamento({ problema }: { problema: Problema }) {
10	  const store = useStore();
11	  const [confirmando, setConfirmando] = useState(false);
12	  const [erro, setErro] = useState<string | null>(null);
13	
14	  const mensagem =
15	    problema.tipo === 'corrompido'
16	      ? 'Os dados salvos neste navegador estão corrompidos e não puderam ser lidos.'
17	      : `Os dados salvos foram criados por uma versão mais nova do app (esquema ${problema.versao}). Para não perdê-los, o app não vai sobrescrevê-los.`;
18	
19	  return (
20	    <main className="mx-auto max-w-xl px-4 py-10">
21	      <Cartao titulo="Não foi possível carregar seus dados">
22	        <div className="space-y-4">
23	          <Alerta tipo="aviso">{mensagem}</Alerta>
24	          <p className="text-sm text-slate-700">
25	            Exporte o conteúdo bruto para guardar uma cópia. Só depois, se quiser, comece do zero: isso apaga o que está salvo.
26	          </p>
27	          {erro ? <Alerta>{erro}</Alerta> : null}
28	          <div className="flex flex-wrap gap-2">
29	            <Botao variante="secundario" onClick={() => baixarArquivo('financas-dados-brutos.json', problema.bruto)}>
30	              Exportar conteúdo bruto
31	            </Botao>
32	            <Botao variante="perigo" onClick={() => setConfirmando(true)}>
33	              Começar do zero
34	            </Botao>
35	          </div>
36	        </div>
37	      </Cartao>
38	      {confirmando ? (
39	        <ConfirmDialog
40	          titulo="Começar do zero?"
41	          mensagem="Os dados salvos atualmente serão substituídos por um app vazio."
42	          rotuloConfirmar="Começar do zero"
43	          perigo
44	          textoDigitado="APAGAR"
45	          onCancelar={() => setConfirmando(false)}
46	          onConfirmar={() => {
47	            const r = store.iniciarVazio();
48	            if (!r.ok) setErro(r.erro);
49	            setConfirmando(false);
50	          }}
51	        />
52	      ) : null}
53	    </main>
54	  );
55	}
