1	import { useCallback, useEffect, useId, useRef, useState, type ReactNode } from 'react';
2	import { atalhos, useAtalhos } from '../lib/atalhos';
3	import { EVENTO_ABRIR_TOUR, marcarTourConcluido, passosTour, tourConcluido } from '../lib/onboarding';
4	import { Botao } from './ui';
5	
6	const FOCAVEIS = 'button:not([disabled]), a[href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
7	
8	/** Moldura de diálogo modal: foco inicial dentro, Tab preso no diálogo, Esc fecha, foco devolvido ao fechar. */
9	function Modal({ titulo, idTitulo, aoFechar, children }: { titulo: string; idTitulo: string; aoFechar: () => void; children: ReactNode }) {
10	  const raiz = useRef<HTMLDivElement>(null);
11	
12	  useEffect(() => {
13	    const anterior = document.activeElement instanceof HTMLElement ? document.activeElement : null;
14	    raiz.current?.querySelector<HTMLElement>(FOCAVEIS)?.focus();
15	    return () => anterior?.focus();
16	  }, []);
17	
18	  useEffect(() => {
19	    const aoTeclar = (e: KeyboardEvent) => {
20	      if (e.key === 'Escape') {
21	        e.stopPropagation();
22	        aoFechar();
23	      } else if (e.key === 'Tab' && raiz.current) {
24	        const itens = Array.from(raiz.current.querySelectorAll<HTMLElement>(FOCAVEIS));
25	        if (itens.length === 0) return;
26	        const primeiro = itens[0];
27	        const ultimo = itens[itens.length - 1];
28	        if (!raiz.current.contains(document.activeElement)) {
29	          e.preventDefault();
30	          primeiro.focus();
31	        } else if (e.shiftKey && document.activeElement === primeiro) {
32	          e.preventDefault();
33	          ultimo.focus();
34	        } else if (!e.shiftKey && document.activeElement === ultimo) {
35	          e.preventDefault();
36	          primeiro.focus();
37	        }
38	      }
39	    };
40	    document.addEventListener('keydown', aoTeclar);
41	    return () => document.removeEventListener('keydown', aoTeclar);
42	  }, [aoFechar]);
43	
44	  return (
45	    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4 print:hidden">
46	      <div ref={raiz} role="dialog" aria-modal="true" aria-labelledby={idTitulo} className="max-h-full w-full max-w-md overflow-y-auto rounded-lg bg-white p-5 shadow-xl">
47	        <h2 id={idTitulo} className="text-lg font-semibold text-slate-900">
48	          {titulo}
49	        </h2>
50	        {children}
51	      </div>
52	    </div>
53	  );
54	}
