1	import { useRef, useState } from 'react';
2	import { Alerta, Botao, Cartao } from './ui';
3	import { ConfirmDialog } from './ConfirmDialog';
4	import { gerarExemplo } from '../data/exemplo';
5	import { hojeISO } from '../domain/date';
6	import type { AppState } from '../domain/types';
7	import { baixarArquivo, lerArquivoTexto } from '../lib/download';
8	import { exportarJson, importarJson } from '../storage/storage';
9	import { usePreferencias } from '../state/preferencias';
10	import { useEstado, useStore } from '../state/store';
11	
12	type Acao = { tipo: 'importar'; estado: AppState } | { tipo: 'apagar' } | { tipo: 'exemplo' } | null;
13	type Mensagem = { tipo: 'erro' | 'sucesso'; texto: string } | null;
14	
15	/** Exportar, importar, exemplo e apagar tudo; vive na página Configurações. */
16	export function SecaoDados() {
17	  const store = useStore();
18	  const { redefinir } = usePreferencias();
19	  const estado = useEstado();
20	  const [acao, setAcao] = useState<Acao>(null);
21	  const [mensagem, setMensagem] = useState<Mensagem>(null);
22	  const entradaArquivo = useRef<HTMLInputElement>(null);
23	  const temDados = estado.contas.length > 0 || estado.transacoes.length > 0;
24	
25	  const exportar = () => {
26	    baixarArquivo(`financas-${hojeISO()}.json`, exportarJson(estado));
27	    setMensagem({ tipo: 'sucesso', texto: 'Arquivo de exportação gerado.' });
28	  };
29	
30	  const escolherArquivo = async (arquivo: File | undefined) => {
31	    if (!arquivo) return;
32	    setMensagem(null);
33	    try {
34	      const r = importarJson(await lerArquivoTexto(arquivo));
35	      if (!r.ok) setMensagem({ tipo: 'erro', texto: r.erro });
36	      else setAcao({ tipo: 'importar', estado: r.valor });
37	    } catch (e) {
38	      setMensagem({ tipo: 'erro', texto: e instanceof Error ? e.message : 'Falha ao ler o arquivo.' });
39	    }
40	    if (entradaArquivo.current) entradaArquivo.current.value = '';
41	  };
42	
43	  const confirmar = () => {
44	    if (!acao) return;
45	    if (acao.tipo === 'apagar') {
46	      store.apagarTudo();
47	      redefinir();
48	      setMensagem({ tipo: 'sucesso', texto: 'Todos os dados foram apagados.' });
49	    } else {
50	      const novo = acao.tipo === 'importar' ? acao.estado : gerarExemplo(hojeISO());
51	      const r = store.substituir(novo);
52	      setMensagem(
53	        r.ok
54	          ? { tipo: 'sucesso', texto: acao.tipo === 'importar' ? 'Dados importados.' : 'Dados de exemplo carregados.' }
55	          : { tipo: 'erro', texto: r.erro },
56	      );
57	    }
58	    setAcao(null);
59	  };
60	
61	  return (
62	    <section aria-labelledby="secao-dados">
63	      <h2 id="secao-dados" className="mb-3 text-xl font-semibold text-slate-900">
64	        Dados
65	      </h2>
66	      <div className="space-y-4">
67	        {mensagem ? <Alerta tipo={mensagem.tipo}>{mensagem.texto}</Alerta> : null}
68	        <Cartao titulo="Backup">
69	          <p className="mb-3 text-sm text-slate-700">
70	            Seus dados ficam apenas neste navegador. Exporte um arquivo JSON para guardar uma cópia ou levar para outro computador.
71	          </p>
72	          <div className="flex flex-wrap gap-2">
73	            <Botao onClick={exportar}>Exportar dados</Botao>
74	            <Botao variante="secundario" onClick={() => entradaArquivo.current?.click()}>
75	              Importar dados
76	            </Botao>
77	            <input
78	              ref={entradaArquivo}
79	              type="file"
80	              accept="application/json,.json"
81	              aria-label="Arquivo de dados para importar"
82	              className="sr-only"
83	              onChange={(e) => void escolherArquivo(e.target.files?.[0])}
84	            />
85	          </div>
86	        </Cartao>
87	        <Cartao titulo="Dados de exemplo">
88	          <p className="mb-3 text-sm text-slate-700">Carrega contas, transações, orçamento, metas e recorrências fictícias para explorar o app.</p>
89	          <Botao variante="secundario" onClick={() => (temDados ? setAcao({ tipo: 'exemplo' }) : confirmarDireto())}>
90	            Carregar dados de exemplo
91	          </Botao>
92	        </Cartao>
93	        <Cartao titulo="Zona de perigo">
94	          <p className="mb-3 text-sm text-slate-700">Remove tudo o que o app guardou neste navegador e volta ao primeiro uso.</p>
95	          <Botao variante="perigo" onClick={() => setAcao({ tipo: 'apagar' })}>
96	            Apagar todos os dados
97	          </Botao>
98	        </Cartao>
99	      </div>
100	
101	      {acao?.tipo === 'importar' ? (
102	        <ConfirmDialog
103	          titulo="Importar dados?"
104	          mensagem="O conteúdo atual será substituído pelo do arquivo. Isso não pode ser desfeito."
105	          rotuloConfirmar="Substituir e importar"
106	          perigo
107	          onCancelar={() => setAcao(null)}
108	          onConfirmar={confirmar}
109	        />
110	      ) : null}
111	      {acao?.tipo === 'exemplo' ? (
112	        <ConfirmDialog
113	          titulo="Carregar dados de exemplo?"
114	          mensagem="Os dados atuais serão substituídos pelos dados de exemplo."
115	          rotuloConfirmar="Substituir"
116	          perigo
117	          onCancelar={() => setAcao(null)}
118	          onConfirmar={confirmar}
119	        />
120	      ) : null}
121	      {acao?.tipo === 'apagar' ? (
122	        <ConfirmDialog
123	          titulo="Apagar todos os dados?"
124	          mensagem="Contas, transações, orçamento, metas e recorrências serão removidos deste navegador."
125	          rotuloConfirmar="Apagar tudo"
126	          perigo
127	          textoDigitado="APAGAR"
128	          onCancelar={() => setAcao(null)}
129	          onConfirmar={confirmar}
130	        />
131	      ) : null}
132	    </section>
133	  );
134	
135	  function confirmarDireto() {
136	    const r = store.substituir(gerarExemplo(hojeISO()));
137	    setMensagem(r.ok ? { tipo: 'sucesso', texto: 'Dados de exemplo carregados.' } : { tipo: 'erro', texto: r.erro });
138	  }
139	}
