11	export const perguntas: Pergunta[] = [
12	  { pergunta: 'Onde ficam os meus dados?', resposta: 'Somente no armazenamento local (localStorage) do seu navegador, neste dispositivo. Nada é enviado a servidores, e não há conta nem login.' },
13	  { pergunta: 'Como faço backup dos meus dados?', resposta: 'Na página Dados, use Exportar para baixar um arquivo JSON com tudo. Guarde-o em local seguro; para restaurar, use Importar e escolha esse arquivo.' },
14	  { pergunta: 'O que acontece se eu limpar os dados do navegador?', resposta: 'Os dados deste app são apagados junto. Por isso vale exportar um backup de tempos em tempos, principalmente antes de limpar o navegador ou trocar de computador.' },
15	  { pergunta: 'Como importo o extrato do banco em CSV?', resposta: 'Em Importar CSV, escolha o arquivo, indique a conta de destino e confira o mapeamento das colunas. Você revisa as linhas antes de confirmar, e lançamentos que parecem duplicados são sinalizados.' },
16	  { pergunta: 'Como funciona a projeção do Dashboard?', resposta: 'A projeção parte do saldo atual e acrescenta, mês a mês, as receitas e despesas recorrentes e as parcelas já lançadas. Ela é uma estimativa baseada no que você cadastrou, não uma previsão.' },
17	  { pergunta: 'Como cadastro um cartão de crédito?', resposta: 'Em Contas, crie uma conta do tipo cartão e informe dia de fechamento, dia de vencimento e limite. A tela Cartões mostra a fatura de cada mês, o limite usado e o disponível.' },
18	  { pergunta: 'Como lanço uma compra parcelada?', resposta: 'Na tela Cartões, escolha a compra parcelada e informe valor total, número de parcelas e data da primeira. O app cria uma despesa por mês, e cada parcela cai na fatura do ciclo correto.' },
19	  { pergunta: 'Pagar a fatura conta como despesa?', resposta: 'Não. O pagamento move dinheiro da conta de origem para o cartão e não entra nos totais de receitas e despesas, porque as compras já foram contadas como despesa.' },
20	  { pergunta: 'Como funciona o orçamento?', resposta: 'Você define um limite mensal por categoria. O app compara com as despesas do mês e mostra quanto resta ou se o limite foi ultrapassado.' },
21	  { pergunta: 'Os valores têm erro de arredondamento?', resposta: 'Não. Todos os valores são guardados em centavos inteiros, então somas e parcelas fecham exatamente.' },
22	  { pergunta: 'Como apago tudo ou carrego dados de exemplo?', resposta: 'Na página Dados você encontra Apagar tudo e Carregar exemplo. As duas ações pedem confirmação antes de substituir o que existe.' },
23	];
