29	export function AjudaPage() {
30	  const prefixo = useId();
31	  const [busca, setBusca] = useState('');
32	  const [abertas, setAbertas] = useState<ReadonlySet<number>>(new Set());
33	
34	  const termo = normalizar(busca.trim());
35	  const visiveis = perguntas.map((p, i) => ({ ...p, i })).filter((p) => normalizar(`${p.pergunta} ${p.resposta}`).includes(termo));
36	
37	  const alternar = (i: number) => {
38	    const novo = new Set(abertas);
39	    if (!novo.delete(i)) novo.add(i);
40	    setAbertas(novo);
41	  };
42	
43	  return (
44	    <div className="space-y-4">
45	      <TituloPagina
46	        acoes={
47	          <Botao variante="secundario" onClick={pedirTour}>
48	            Rever o tour
49	          </Botao>
50	        }
51	      >
52	        Ajuda
53	      </TituloPagina>
54	
55	      <Cartao titulo="Perguntas frequentes">
56	        <CampoTexto label="Buscar nas perguntas" type="search" value={busca} onChange={(e) => setBusca(e.target.value)} autoComplete="off" />
57	        <div className="mt-3">
58	          {visiveis.length === 0 ? (
59	            <EstadoVazio titulo="Nenhuma pergunta encontrada">{`Nada corresponde a "${busca.trim()}". Tente outras palavras.`}</EstadoVazio>
60	          ) : (
61	            <ul className="divide-y divide-slate-200">
62	              {visiveis.map((p) => {
63	                const aberta = abertas.has(p.i);
64	                const idResposta = `${prefixo}-r${p.i}`;
65	                return (
66	                  <li key={p.i}>
67	                    <h3>
68	                      <button
69	                        type="button"
70	                        aria-expanded={aberta}
71	                        aria-controls={idResposta}
72	                        onClick={() => alternar(p.i)}
73	                        className="flex w-full items-center justify-between gap-3 py-3 text-left text-sm font-medium text-slate-900 focus:outline-none focus:ring-2 focus:ring-emerald-600"
74	                      >
75	                        <span>{p.pergunta}</span>
76	                        <span aria-hidden="true">{aberta ? '−' : '+'}</span>
77	                      </button>
78	                    </h3>
79	                    <div id={idResposta} role="region" aria-label={p.pergunta} hidden={!aberta} className="pb-3 text-sm text-slate-700">
80	                      {p.resposta}
81	                    </div>
82	                  </li>
83	                );
84	              })}
85	            </ul>
86	          )}
87	        </div>
88	      </Cartao>
89	
90	      <Cartao titulo="Atalhos de teclado">
91	        <TabelaAtalhos />
92	      </Cartao>
93	    </div>
94	  );
95	}
