/* Utilitárias de layout reutilizáveis (CSS puro, sem Tailwind). */
.sr-somente {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.pilha {
  display: flex;
  flex-direction: column;
  gap: var(--esp-4);
  min-width: 0;
}
.pilha--p { gap: var(--esp-2); }
.pilha--g { gap: var(--esp-8); }

.linha {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--esp-2);
  min-width: 0;
}
.linha--entre { justify-content: space-between; }
.linha--fim { justify-content: flex-end; }
.linha--centro { justify-content: center; }
.linha--g { gap: var(--esp-4); }

.grade {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));
  gap: var(--esp-4);
  min-width: 0;
}
.grade--2 { grid-template-columns: 1fr; }
@media (min-width: 640px) {
  .grade--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

.texto-suave { color: var(--cor-texto-suave); }
.texto-mudo { color: var(--cor-texto-mudo); }
.texto-pequeno { font-size: var(--texto-sm); }
.texto-mini { font-size: var(--texto-xs); }

.so-impressao { display: none; }
@media print {
  .nao-imprimir { display: none !important; }
  .so-impressao { display: block; }
}

