input.content:
.ui-botao {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
  border-radius: var(--raio-pequeno);
  padding: var(--esp-2) var(--esp-3);
  font: inherit;
  font-size: var(--texto-sm);
  font-weight: 500;
  cursor: pointer;
}
.ui-botao:focus { outline: none; }
.ui-botao:focus-visible { outline: 2px solid var(--cor-foco); outline-offset: 1px; }
.ui-botao:disabled { cursor: not-allowed; opacity: 0.5; }
.ui-botao--primario { background: var(--cor-primaria); color: var(--cor-sobre-primaria); }
.ui-botao--primario:hover:not(:disabled) { background: var(--cor-primaria-hover); }
.ui-botao--secundario { background: var(--cor-superficie); color: var(--cor-texto); border-color: var(--cor-borda-forte); }
.ui-botao--secundario:hover:not(:disabled) { background: var(--cor-superficie-alt); }
.ui-botao--perigo { background: var(--cor-perigo); color: var(--cor-sobre-primaria); }
.ui-botao--perigo:hover:not(:disabled) { background: var(--cor-perigo-hover); }
.ui-botao--link { background: transparent; color: var(--cor-primaria); text-decoration: underline; }
.ui-botao--link:hover:not(:disabled) { color: var(--cor-primaria-hover); }

.ui-campo { min-width: 0; }
.ui-campo__rotulo {
  display: block;
  margin-bottom: var(--esp-1);
  font-size: var(--texto-sm);
  font-weight: 500;
  color: var(--cor-texto-suave);
}
.ui-campo__controle {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  border: 1px solid var(--cor-borda-forte);
  border-radius: var(--raio-pequeno);
  background: var(--cor-superficie);
  padding: var(--esp-2) var(--esp-3);
  font: inherit;
  font-size: var(--texto-sm);
  color: var(--cor-texto);
}
.ui-campo__controle:focus { outline: none; }
.ui-campo__controle:focus-visible { outline: 2px solid var(--cor-foco); outline-offset: 0; }
.ui-campo__controle--erro { border-color: var(--cor-perigo); }
.ui-campo__erro { margin: var(--esp-1) 0 0; font-size: var(--texto-sm); color: var(--cor-perigo); }
.ui-campo__dica { margin: var(--esp-1) 0 0; font-size: var(--texto-xs); color: var(--cor-texto-mudo); }

.ui-cartao {
  min-width: 0;
  box-sizing: border-box;
  border: 1px solid var(--cor-borda);
  border-radius: 0.625rem;
  background: var(--cor-superficie);
  padding: var(--esp-4);
  box-shadow: var(--sombra);
}
.ui-cartao__cabecalho {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--esp-2);
  margin-bottom: var(--esp-3);
}
.ui-cartao__titulo { margin: 0; font-size: var(--texto-base); font-weight: 600; color: var(--cor-texto); }

.ui-titulo-pagina {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--esp-3);
  margin-bottom: var(--esp-4);
}
.ui-titulo-pagina__texto { margin: 0; font-size: var(--texto-2xl); font-weight: 700; color: var(--cor-texto); }

.ui-vazio {
  border: 1px dashed var(--cor-borda-forte);
  border-radius: 0.625rem;
  background: var(--cor-superficie);
  padding: var(--esp-6);
  text-align: center;
}
.ui-vazio__titulo { margin: 0; font-weight: 500; color: var(--cor-texto); }
.ui-vazio__texto { margin: var(--esp-1) 0 0; font-size: var(--texto-sm); color: var(--cor-texto-mudo); }
.ui-vazio__acao { display: flex; justify-content: center; margin-top: var(--esp-3); }

.ui-alerta {
  border: 1px solid;
  border-radius: var(--raio-pequeno);
  padding: var(--esp-2) var(--esp-3);
  font-size: var(--texto-sm);
}
.ui-alerta--erro { border-color: var(--cor-perigo); background: var(--cor-perigo-suave); color: var(--cor-perigo); }
.ui-alerta--aviso { border-color: var(--cor-aviso); background: var(--cor-aviso-suave); color: var(--cor-aviso); }
.ui-alerta--sucesso { border-color: var(--cor-sucesso); background: var(--cor-sucesso-suave); color: var(--cor-sucesso); }

.ui-valor { white-space: nowrap; font-weight: 500; font-variant-numeric: tabular-nums; }
.ui-valor--negativo { color: var(--cor-perigo); }
.ui-valor--positivo { color: var(--cor-sucesso); }
.ui-valor--zero { color: var(--cor-texto-suave); }

/* Moldura modal compartilhada (ConfirmDialog e Onboarding). */
.ui-modal-fundo {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--esp-4);
  background: rgb(15 23 42 / 0.5);
}
.ui-modal {
  box-sizing: border-box;
  width: 100%;
  max-width: 28rem;
  max-height: 100%;
  overflow-y: auto;
  border-radius: 0.625rem;
  background: var(--cor-superficie);
  color: var(--cor-texto);
  padding: var(--esp-5);
  box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.25);
}
.ui-modal__titulo { margin: 0; font-size: var(--texto-lg); font-weight: 600; color: var(--cor-texto); }
@media print {
  .ui-modal-fundo--sem-impressao { display: none; }
}

